import json
import numpy as np

test_input = np.array([
    [7, 7, 5, 5, 7, 7, 5, 7],
    [7, 7, 5, 5, 5, 7, 7, 7],
    [7, 7, 5, 5, 7, 7, 7, 7],
    [7, 7, 5, 5, 7, 7, 7, 7],
    [5, 7, 5, 5, 7, 7, 7, 7],
    [7, 5, 5, 5, 7, 5, 7, 5],
    [7, 7, 5, 5, 7, 7, 5, 7],
    [7, 7, 5, 5, 5, 7, 7, 7],
    [7, 7, 5, 5, 7, 7, 7, 7],
    [5, 5, 5, 5, 5, 5, 5, 5],
    [5, 7, 5, 5, 7, 7, 7, 5],
    [7, 7, 5, 5, 7, 5, 7, 7]
])

accent_cols = {0, 5, 7}

def transform(row):
    if np.all(row == 5):
        return [2, 2, 2, 2, 2, 2, 2, 2]
    output = []
    for c, v in enumerate(row):
        if v == 5:
            if c in accent_cols:
                output.append(2)
            else:
                output.append(5)
        else:
            output.append(7)
    return output

output_grid = np.array([transform(row) for row in test_input])

action = {"action": "submit", "grid": output_grid.tolist()}
print(json.dumps(action))

